const fs = require('fs');
const path = require('path');

const configPath = path.join(__dirname, 'config.json');
const outPath = path.join(__dirname, 'config.out.json');

const defaults = { port: 3000, host: '127.0.0.1' };

let config = {};
if (fs.existsSync(configPath)) {
  const raw = fs.readFileSync(configPath, 'utf8').trim();
  config = raw ? JSON.parse(raw) : {};
}

const result = { ...defaults, ...config };
if (result.port === undefined || result.port === null) result.port = defaults.port;
if (result.host === undefined || result.host === null) result.host = defaults.host;

fs.writeFileSync(outPath, JSON.stringify(result, null, 2) + '\n');
console.log('wrote', outPath, JSON.stringify(result));

